(()=>{const trim=()=>{const b=document.getElementById("live-rows");if(b)while(b.children.length>500)b.lastElementChild.remove()},filter=()=>{const q=(document.getElementById("live-filter")?.value||"").toLowerCase();document.querySelectorAll("#live-rows tr").forEach(r=>r.hidden=!!q&&!((r.dataset.sql||"").toLowerCase().includes(q)||r.textContent.toLowerCase().includes(q)))};document.addEventListener("htmx:sseBeforeMessage",e=>{if(document.body.dataset.livePaused==="true")e.preventDefault()});document.addEventListener("htmx:sseMessage",()=>{trim();filter()});document.addEventListener("input",e=>{if(e.target.id==="live-filter")filter()});document.addEventListener("click",async e=>{const p=e.target.closest("[data-live-pause]");if(p){const paused=document.body.dataset.livePaused!=="true";document.body.dataset.livePaused=String(paused);p.setAttribute("aria-pressed",String(paused));p.textContent=paused?"继续":"暂停"}const c=e.target.closest("[data-copy]");if(c){const el=document.getElementById(c.dataset.copy);if(el)try{await navigator.clipboard.writeText(el.textContent);c.textContent="已复制";setTimeout(()=>c.textContent="复制 SQL",1500)}catch(_){c.textContent="复制失败"}}});document.addEventListener("htmx:afterSwap",()=>{trim();filter()})})();
